#include <iostream>
#include <vector>

void join(std::vector<int>& a, int lo, int mid, int hi) {
    std::vector<int> tmp;
    int i = lo;
    int j = mid + 1;

    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {
            tmp.push_back(a[i]);
            i++;
        } else {
            tmp.push_back(a[j]);
            j++;
        }
    }

    for (int x = 0; x < static_cast<int>(tmp.size()); x++) {
        a[lo + x] = tmp[x];
    }
}

int main() {
    std::vector<int> a = {{l1}, {l2}, {l3}, {l4}, {r1}, {r2}, {r3}, {r4}};
    join(a, 0, 3, 7);

    std::cout << "合并法：";
    for (int i = 0; i < 8; i++) {
        std::cout << a[i] << " ";
    }
    std::cout << "\n";
    return 0;
}

